using System;
using System.Collections.Generic;
using System.Linq;
abstract record Document {
    public sealed record Text(string Value) : Document;
    public sealed record Line : Document;
    public sealed record Softline : Document;
    public sealed record Hardline : Document;
    public sealed record BreakParent : Document;
    public sealed record Suffix(string Value) : Document;
    public sealed record IfBreak(string Broken, string Flat) : Document;
    public sealed record Group(int Id, Document Child) : Document;
    public sealed record Nest(int Amount, Document Child) : Document;
    public sealed record Align(Document Child) : Document;
    public sealed record Concat(List<Document> Children) : Document;
    public bool Forced => this switch {
        Hardline or BreakParent => true, Group g => g.Child.Forced, Nest n => n.Child.Forced, Align a => a.Child.Forced, Concat c => c.Children.Any(x => x.Forced), _ => false
    };
    public int GroupCount => this switch {
        Group g => 1 + g.Child.GroupCount, Nest n => n.Child.GroupCount, Align a => a.Child.GroupCount, Concat c => c.Children.Sum(x => x.GroupCount), _ => 0
    };
}
static class Docs {
    public static Document Text(string value) => new Document.Text(value);
    public static Document Concat(IEnumerable<Document> parts) {
        List<Document> result = new();
        void Flatten(Document document) {
            if (document is Document.Concat c) foreach (Document child in c.Children) Flatten(child);
            else if (document is Document.Text t) {
                if (t.Value.Length == 0) return;
                if (result.LastOrDefault() is Document.Text previous) result[^1] = new Document.Text(previous.Value + t.Value);
                else result.Add(document);
            }
            else result.Add(document);
        }
        foreach (Document part in parts) Flatten(part);
        return result.Count == 0 ? Text("") : result.Count == 1 ? result[0] : new Document.Concat(result);
    }
    public static Document Concat(params Document[] parts) => Concat((IEnumerable<Document>)parts);
    public static Document Nest(int n, Document child) => new Document.Nest(n, child);
    public static Document Align(Document child) => new Document.Align(child);
    public static Document Line() => new Document.Line();
    public static Document Softline() => new Document.Softline();
    public static Document Hardline() => new Document.Hardline();
    public static Document Suffix(string value) => new Document.Suffix(value);
    public static Document BreakParent() => new Document.BreakParent();
    public static Document IfBreak(string broken, string flat) => new Document.IfBreak(broken, flat);
}
sealed class DocBuilder {
    int next;
    public Document Group(Document child) => new Document.Group(next++, child);
}

using System;
using System.Collections.Generic;
using System.Linq;
sealed class SourceError(int line, int column, string reason) : Exception(reason) {
    public int Line {
        get;
    } = line;
    public int Column {
        get;
    } = column;
    public string Reason {
        get;
    } = reason;
}
sealed record Comment(string Text, int Line, int Column, int Blank, bool LineComment) {
    public bool Own {
        get;
        set;
    }
}
sealed record Token(string Text, string Kind, int Line, int Column, int Blank) {
    public List<Comment> Leading {
        get;
    } = new();
    public List<Comment> Trailing {
        get;
    } = new();
}
readonly record struct Occurrence(bool IsToken, int Index);
sealed class Lexed {
    public List<Token> Tokens {
        get;
    } = new();
    public List<Comment> Comments {
        get;
    } = new();
    public List<Occurrence> Order {
        get;
    } = new();
}
static class Lexer {
    public static bool Letter(char c) => c is >= 'A' and <= 'Z' or >= 'a' and <= 'z';
    public static bool Digit(char c) => c is >= '0' and <= '9';
    public static string Trim(string text) => text.TrimEnd(' ');
    public static Lexed Lex(IReadOnlyList<string> lines) {
        Lexed result = new();
        int previous = 0;
        for (int row = 0; row < lines.Count; row++) {
            string line = lines[row];
            int i = 0;
            while (i < line.Length) {
                if (line[i] == ' ') {
                    i++;
                    continue;
                }
                int start = i, lineNumber = row + 1, blank = Math.Max(0, lineNumber - previous - 1);
                SourceError Failure(string reason) => new(lineNumber, start + 1, reason);
                if (line.AsSpan(i).StartsWith("//")) {
                    result.Order.Add(new(false, result.Comments.Count));
                    result.Comments.Add(new(Trim(line[i..]), lineNumber, i + 1, blank, true));
                    previous = lineNumber;
                    break;
                }
                if (line.AsSpan(i).StartsWith("/*")) {
                    int end = line.IndexOf("*/", i + 2, StringComparison.Ordinal);
                    if (end < 0) throw Failure("unterminated comment");
                    result.Order.Add(new(false, result.Comments.Count));
                    result.Comments.Add(new(line[i..(end + 2)], lineNumber, i + 1, blank, false));
                    previous = lineNumber;
                    i = end + 2;
                    continue;
                }
                string kind;
                if (Letter(line[i]) || line[i] == '_') {
                    i++;
                    while (i < line.Length && (Letter(line[i]) || Digit(line[i]) || line[i] == '_')) i++;
                    kind = new[] {
                        "int", "float", "bool", "string", "void", "if", "else", "while", "for", "return", "break", "continue", "true", "false", "switch", "case", "default"
                    }.Contains(line[start..i]) ? "keyword" : "identifier";
                } else if (Digit(line[i])) {
                    i++;
                    while (i < line.Length && Digit(line[i])) i++;
                    if (i + 1 < line.Length && line[i] == '.' && Digit(line[i + 1])) {
                        i += 2;
                        while (i < line.Length && Digit(line[i])) i++;
                    }
                    kind = "number";
                } else if (line[i] == '"') {
                    i++;
                    bool closed = false;
                    while (i < line.Length) {
                        if (line[i] == '\\') i += 2;
                        else if (line[i] == '"') {
                            i++;
                            closed = true;
                            break;
                        } else i++;
                    }
                    if (!closed) throw Failure("unterminated string");
                    kind = "string";
                } else if (i + 1 < line.Length && new[] {
                    "<=", ">=", "==", "!=", "&&", "||", "+=", "-=", "*=", "/=", "%="
                }.Contains(line.Substring(i, 2))) {
                    i += 2;
                    kind = "symbol";
                }
                else if ("+-*/%<>=!()[]{},;.?:".Contains(line[i])) {
                    i++;
                    kind = "symbol";
                }
                else throw Failure($"unexpected character '{line[i]}'");
                result.Order.Add(new(true, result.Tokens.Count));
                result.Tokens.Add(new(line[start..i], kind, lineNumber, start + 1, blank));
                previous = lineNumber;
            }
        }
        result.Tokens.Add(new("", "end", lines.Count + 1, 1, 0));
        return result;
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
sealed record SyntaxNode(string Kind, List<int> Tokens, List<SyntaxNode> Children, int Start, int End, int? Trailing = null);
sealed class Parser(List<Token> tokens) {
    int index;
    Token Peek => tokens[index];
    string Text => Peek.Text;
    int Take() => index++;
    SourceError Failure(string expected) => new(Peek.Line, Peek.Column, $"expected {expected}, found {(Peek.Kind == "end" ? "end of file" : "'" + Text + "'")}");
    int Symbol(string value) {
        if (Text != value) throw Failure("'" + value + "'");
        return Take();
    }
    int Identifier() {
        if (Peek.Kind != "identifier") throw Failure("identifier");
        return Take();
    }
    int ReadType() {
        if (!IsType(Text)) throw Failure("type");
        return Take();
    }
    SyntaxNode Node(string kind, List<int> ts, List<SyntaxNode> children, int start) => new(kind, ts, children, start, Math.Max(0, index - 1));
    SyntaxNode Empty() => new("empty", new(), new(), index, index);
    SyntaxNode List(string kind, string open, string close, bool trailing) {
        int start = index;
        List<int> ts = new() {
            Symbol(open)
        };
        List<SyntaxNode> children = new();
        int? tail = null;
        if (Text != close) {
            children.Add(ListElement(kind));
            while (Text == ",") {
                int comma = Take();
                if (trailing && Text == close) {
                    tail = comma;
                    break;
                } ts.Add(comma);
                children.Add(ListElement(kind));
            }
        }
        ts.Add(Symbol(close));
        return Node(kind, ts, children, start) with {
            Trailing = tail
        };
    }
    SyntaxNode ListElement(string kind) {
        if (kind != "params") return kind == "initlist" ? Initializer() : Expression();
        int start = index;
        List<int> ts = new() {
            ReadType(), Identifier()
        };
        List<SyntaxNode> children = new();
        while (Text == "[") {
            int s = index;
            List<int> pair = new() {
                Take(), Symbol("]")
            };
            children.Add(Node("dimension", pair, new(), s));
        }
        return Node("parameter", ts, children, start);
    }
    SyntaxNode Initializer() => Text == "{" ? List("initlist", "{", "}", true) : Expression();
    SyntaxNode Declaration(bool semicolon) {
        int start = index;
        return DeclarationRest(start, new() {
            ReadType(), Identifier()
        }, semicolon);
    }
    SyntaxNode DeclarationRest(int start, List<int> ts, bool semicolon) {
        List<SyntaxNode> children = new();
        while (Text == "[") {
            int s = index, open = Take();
            List<SyntaxNode> content = Text == "]" ? new() : new() {
                Expression()
            };
            int close = Symbol("]");
            children.Add(Node("dimension", new() {
                open, close
            }, content, s));
        }
        if (Text == "=") {
            ts.Add(Take());
            children.Add(Initializer());
        } if (semicolon) ts.Add(Symbol(";"));
        return Node("decl", ts, children, start);
    }
    SyntaxNode Item() {
        int start = index;
        List<int> ts = new() {
            ReadType(), Identifier()
        };
        if (Text != "(") return DeclarationRest(start, ts, true);
        SyntaxNode parameters = List("params", "(", ")", false), block = Block();
        return Node("function", ts, new() {
            parameters, block
        }, start);
    }
    SyntaxNode Block() {
        int start = index, open = Symbol("{");
        List<SyntaxNode> statements = new();
        while (Text != "}" && Peek.Kind != "end") statements.Add(Statement());
        int close = Symbol("}");
        return Node("block", new() {
            open, close
        }, statements, start);
    }
    SyntaxNode Statement() {
        int start = index;
        if (Text == "{") return Block();
        if (IsType(Text)) return Declaration(true);
        switch (Text) {
            case "if": case "while": {
                string kind = Text;
                int keyword = Take(), open = Symbol("(");
                SyntaxNode condition = Expression();
                int close = Symbol(")");
                SyntaxNode body = Statement();
                List<int> ts = new() {
                    keyword, open, close
                };
                List<SyntaxNode> children = new() {
                    condition, body
                };
                if (kind == "if" && Text == "else") {
                    ts.Add(Take());
                    children.Add(Statement());
                } return Node(kind, ts, children, start);
            }
            case "for": {
                int keyword = Take(), open = Symbol("(");
                SyntaxNode initial = Text == ";" ? Empty() : IsType(Text) ? Declaration(false) : Simple();
                int first = Symbol(";");
                SyntaxNode condition = Text == ";" ? Empty() : Expression();
                int second = Symbol(";");
                SyntaxNode update = Text == ")" ? Empty() : Simple();
                int close = Symbol(")");
                SyntaxNode body = Statement();
                return Node("for", new() {
                    keyword, open, first, second, close
                }, new() {
                    initial, condition, update, body
                }, start);
            }
            case "switch": {
                int keyword = Take(), open = Symbol("(");
                SyntaxNode condition = Expression();
                int close = Symbol(")"), left = Symbol("{");
                List<SyntaxNode> children = new() {
                    condition
                };
                while (Text is "case" or "default") {
                    int s = index, label = Take();
                    string kind = tokens[label].Text;
                    List<SyntaxNode> body = new();
                    if (kind == "case") body.Add(Expression());
                    int colon = Symbol(":");
                    while (Text is not ("case" or "default" or "}") && Peek.Kind != "end") body.Add(Statement());
                    children.Add(Node(kind, new() {
                        label, colon
                    }, body, s));
                }
                int right = Symbol("}");
                return Node("switch", new() {
                    keyword, open, close, left, right
                }, children, start);
            }
            case "return": {
                int keyword = Take();
                List<SyntaxNode> children = Text == ";" ? new() : new() {
                    Expression()
                };
                int semi = Symbol(";");
                return Node("return", new() {
                    keyword, semi
                }, children, start);
            }
            case "break": case "continue": {
                int keyword = Take();
                string kind = tokens[keyword].Text;
                int semi = Symbol(";");
                return Node(kind, new() {
                    keyword, semi
                }, new(), start);
            }
            default: {
                SyntaxNode expression = Simple();
                int semi = Symbol(";");
                return Node("statement", new() {
                    semi
                }, new() {
                    expression
                }, start);
            }
        }
    }
    SyntaxNode Simple() {
        int start = index;
        SyntaxNode left = Expression();
        if (Text is not ("=" or "+=" or "-=" or "*=" or "/=" or "%=")) return Node("exprstmt", new(), new() {
            left
        }, start);
        int op = Take();
        SyntaxNode right = Expression();
        return Node("assign", new() {
            op
        }, new() {
            left, right
        }, start);
    }
    SyntaxNode Expression() {
        int start = index;
        SyntaxNode condition = Binary(1);
        if (Text != "?") return condition;
        int question = Take();
        SyntaxNode yes = Expression();
        int colon = Symbol(":");
        SyntaxNode no = Expression();
        return Node("conditional", new() {
            question, colon
        }, new() {
            condition, yes, no
        }, start);
    }
    SyntaxNode Binary(int precedence) {
        int start = index;
        SyntaxNode left = precedence == 6 ? Unary() : Binary(precedence + 1);
        while (Precedence(Text) == precedence) {
            int op = Take();
            SyntaxNode right = precedence == 6 ? Unary() : Binary(precedence + 1);
            left = Node("binary", new() {
                op
            }, new() {
                left, right
            }, start);
        } return left;
    }
    SyntaxNode Unary() {
        int start = index;
        if (Text is "-" or "!") {
            int op = Take();
            SyntaxNode child = Unary();
            return Node("unary", new() {
                op
            }, new() {
                child
            }, start);
        }
        SyntaxNode target = Primary();
        while (true) {
            switch (Text) {
                case "(": {
                    SyntaxNode args = List("args", "(", ")", false);
                    target = Node("call", new(), new() {
                        target, args
                    }, start);
                    break;
                }
                case "[": {
                    int open = Take();
                    SyntaxNode expression = Expression();
                    int close = Symbol("]");
                    target = Node("index", new() {
                        open, close
                    }, new() {
                        target, expression
                    }, start);
                    break;
                }
                case ".": {
                    int dot = Take(), name = Identifier();
                    target = Node("member", new() {
                        dot, name
                    }, new() {
                        target
                    }, start);
                    break;
                }
                default: return target;
            }
        }
    }
    SyntaxNode Primary() {
        int start = index;
        if (Peek.Kind is "identifier" or "number" or "string" || Text is "true" or "false") return Node("atom", new() {
            Take()
        }, new(), start);
        if (Text == "(") {
            int open = Take();
            SyntaxNode child = Expression();
            int close = Symbol(")");
            return Node("paren", new() {
                open, close
            }, new() {
                child
            }, start);
        } throw Failure("expression");
    }
    public static bool IsType(string text) => text is "int" or "float" or "bool" or "string" or "void";
    public static int Precedence(string text) => text switch {
        "||" => 1, "&&" => 2, "==" or "!=" => 3, "<" or "<=" or ">" or ">=" => 4, "+" or "-" => 5, "*" or "/" or "%" => 6, _ => 0
    };
    public static List<SyntaxNode> Parse(List<Token> tokens) {
        Parser parser = new(tokens);
        List<SyntaxNode> items = new();
        while (parser.Peek.Kind != "end") items.Add(parser.Item());
        return items;
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
readonly record struct Command(int Indent, bool Flat, Document Document);
sealed record Printed(List<string> Lines, Dictionary<int, string> Modes);
static class Printer {
    public static bool Fits(int width, Command first, List<Command> stack) {
        if (width < 0) return false;
        int remaining = width;
        List<Command> check = new(stack) {
            first
        };
        while (check.Count > 0) {
            Command command = check[^1];
            check.RemoveAt(check.Count - 1);
            int i = command.Indent;
            bool flat = command.Flat;
            switch (command.Document) {
                case Document.Text t: remaining -= t.Value.Length;
                break;
                case Document.IfBreak b: remaining -= flat ? b.Flat.Length : b.Broken.Length;
                break;
                case Document.Line: if (flat) remaining--;
                else return true;
                break;
                case Document.Softline: if (!flat) return true;
                break;
                case Document.Hardline: return true;
                case Document.Concat c: foreach (Document part in c.Children.AsEnumerable().Reverse()) check.Add(new(i, flat, part));
                break;
                case Document.Group g: check.Add(new(i, g.Forced ? false : flat, g.Child));
                break;
                case Document.Nest n: check.Add(new(i, flat, n.Child));
                break;
                case Document.Align a: check.Add(new(i, flat, a.Child));
                break;
            }
            if (remaining < 0) return false;
        }
        return true;
    }
    public static Printed Print(Document document, int width, int column) {
        List<Command> stack = new() {
            new(0, false, document)
        };
        List<string> lines = new(), pending = new();
        Dictionary<int, string> modes = new();
        string current = "";
        int col = 0;
        void FinalizeLine() {
            string value = Lexer.Trim(current);
            if (pending.Count > 0) {
                string comment = string.Join(" ", pending);
                value += column > 0 && value.Length < column - 1 && column - 1 + comment.Length <= width ? new string(' ', column - 1 - value.Length) : " ";
                value += comment;
                pending.Clear();
            } lines.Add(value);
        }
        while (stack.Count > 0) {
            Command command = stack[^1];
            stack.RemoveAt(stack.Count - 1);
            int i = command.Indent;
            bool flat = command.Flat;
            Document doc = command.Document;
            switch (doc) {
                case Document.Text t: current += t.Value;
                col += t.Value.Length;
                break;
                case Document.IfBreak b: {
                    string value = flat ? b.Flat : b.Broken;
                    current += value;
                    col += value.Length;
                    break;
                }
                case Document.Line: case Document.Softline: case Document.Hardline:
                if (doc is Document.Hardline || !flat) {
                    FinalizeLine();
                    current = new string(' ', i);
                    col = i;
                } else if (doc is Document.Line) {
                    current += " ";
                    col++;
                } break;
                case Document.Concat c: foreach (Document part in c.Children.AsEnumerable().Reverse()) stack.Add(new(i, flat, part));
                break;
                case Document.Nest n: stack.Add(new(i + n.Amount, flat, n.Child));
                break;
                case Document.Align a: stack.Add(new(col, flat, a.Child));
                break;
                case Document.Suffix s: pending.Add(s.Value);
                break;
                case Document.Group g: {
                    string mode = flat ? "flat" : g.Forced ? "forced" : Fits(width - col, new(i, true, g.Child), stack) ? "flat" : "break";
                    modes[g.Id] = mode;
                    stack.Add(new(i, mode == "flat", g.Child));
                    break;
                }
            }
        }
        FinalizeLine();
        return new(lines, modes);
    }
}

using System;
using System.IO;
using System.Globalization;
using System.Collections.Generic;
using System.Linq;
using static Docs;
sealed class Profile {
    public Dictionary<string, string> Values {
        get;
    } = new();
    public bool Yes(string key) => Values[key] == "yes";
    public int Number(string key) => int.Parse(Values[key], CultureInfo.InvariantCulture);
    public bool Kr => Values["brace_style"] == "kr";
}
sealed class Construction(List<Token> tokens, Profile profile) {
    public List<Token> Tokens {
        get;
    } = tokens;
    readonly bool[] originalTrailing = tokens.Select(t => t.Trailing.Count != 0).ToArray();
    readonly DocBuilder docs = new();
    Document Space() => Text(profile.Yes("space_around_operators") ? " " : "");
    Document KeywordSpace() => Text(profile.Yes("space_after_keyword") ? " " : "");
    Document OperatorLine() => profile.Yes("space_around_operators") ? Line() : Softline();
    public Document Separator(int blank) => Concat(Enumerable.Range(0, 1 + Math.Min(blank, profile.Number("max_blank_lines"))).Select(_ => Hardline()));
    public int Preblank(int token) => Tokens[token].Leading.FirstOrDefault()?.Blank ?? Tokens[token].Blank;
    public Document Comments(IReadOnlyList<Comment> comments, int? next) {
        List<Document> parts = new();
        for (int i = 0; i < comments.Count; i++) {
            Comment comment = comments[i];
            parts.Add(Text(comment.Text));
            int? blank = i + 1 < comments.Count ? comments[i + 1].Blank : next;
            if (blank.HasValue) parts.Add(comment.Own ? Separator(blank.Value) : Text(" "));
        }
        return Concat(parts);
    }
    Document Trailing(int token) => Tokens[token].Trailing.Count == 0 ? Text("") : Suffix(string.Join(" ", Tokens[token].Trailing.Select(c => c.Text)));
    Document TokenWith(int token, IReadOnlyList<Comment> leading) => Concat(Comments(leading, Tokens[token].Blank), Text(Tokens[token].Text), Trailing(token));
    Document T(int token) => TokenWith(token, Tokens[token].Leading);
    Document Group(Document child) => docs.Group(child);
    int Level(SyntaxNode node) => node.Kind switch {
        "conditional" => 0, "binary" => Parser.Precedence(Tokens[node.Tokens[0]].Text), "unary" => 7, _ => 8
    };
    SyntaxNode Open(SyntaxNode node, int required) {
        SyntaxNode current = node;
        while (profile.Yes("remove_parens") && current.Kind == "paren" && Level(current.Children[0]) >= required && Tokens[current.Tokens[0]].Leading.Count == 0 && Tokens[current.Tokens[1]].Leading.Count == 0) {
            SyntaxNode child = current.Children[0];
            Token left = Tokens[current.Tokens[0]], right = Tokens[current.Tokens[1]];
            List<Comment> first = new(left.Trailing), last = new(right.Trailing);
            left.Trailing.Clear();
            right.Trailing.Clear();
            Tokens[child.Start].Trailing.InsertRange(0, first);
            Tokens[child.End].Trailing.AddRange(last);
            current = child;
        }
        return current;
    }
    Document List(SyntaxNode node) {
        int left = node.Tokens[0], right = node.Tokens[^1];
        if (node.Children.Count == 0) return Concat(T(left), T(right));
        bool forced = Enumerable.Range(node.Start, node.End - node.Start).Any(i => originalTrailing[i]);
        List<Document> inside = new() {
            Softline()
        };
        for (int i = 0; i < node.Children.Count; i++) {
            SyntaxNode child = node.Children[i];
            if (i > 0) inside.AddRange(new[] {
                T(node.Tokens[i]), Line()
            });
            inside.Add(node.Kind == "params" ? Parameter(child) : node.Kind == "initlist" ? Initializer(child) : Expression(child, 0));
        }
        if (node.Kind == "initlist") {
            inside.Add(IfBreak(",", ""));
            if (node.Trailing is int tail) inside.Add(Trailing(tail));
        }
        return Group(Concat(forced ? BreakParent() : Text(""), T(left), Nest(profile.Number("indent"), Concat(inside)), Softline(), T(right)));
    }
    Document Parameter(SyntaxNode node) {
        List<Document> parts = new() {
            T(node.Tokens[0]), Text(" "), T(node.Tokens[1])
        };
        foreach (SyntaxNode dimension in node.Children) parts.AddRange(new[] {
            T(dimension.Tokens[0]), T(dimension.Tokens[1])
        });
        return Concat(parts);
    }
    public Document Declaration(SyntaxNode node) {
        List<Document> parts = new() {
            T(node.Tokens[0]), Text(" "), T(node.Tokens[1])
        };
        SyntaxNode? initial = null;
        foreach (SyntaxNode child in node.Children) {
            if (child.Kind == "dimension") {
                parts.Add(T(child.Tokens[0]));
                if (child.Children.Count > 0) parts.Add(Expression(child.Children[0], 0));
                parts.Add(T(child.Tokens[1]));
            } else initial = child;
        }
        foreach (int t in node.Tokens.Skip(2)) {
            if (Tokens[t].Text == "=") parts.AddRange(new[] {
                Space(), T(t), Space(), Initializer(initial!)
            });
            else parts.Add(T(t));
        }
        return Concat(parts);
    }
    Document Initializer(SyntaxNode node) => node.Kind == "initlist" ? List(node) : Expression(node, 0);
    (List<Comment> H, List<Comment> G) Closing(int token) {
        List<Comment> comments = Tokens[token].Leading;
        int split = comments.FindLastIndex(c => c.Own) + 1;
        return (comments.Take(split).ToList(), comments.Skip(split).ToList());
    }
    Document Block(SyntaxNode node) {
        int close = node.Tokens[1];
        var (h, g) = Closing(close);
        if (node.Children.Count == 0 && h.Count == 0) return Concat(T(node.Tokens[0]), TokenWith(close, g));
        List<Document> inside = new() {
            Hardline()
        };
        for (int i = 0; i < node.Children.Count; i++) {
            SyntaxNode child = node.Children[i];
            if (i > 0) inside.Add(Separator(Preblank(child.Start)));
            inside.Add(Statement(child));
        }
        if (h.Count > 0) {
            if (node.Children.Count > 0) inside.Add(Separator(h[0].Blank));
            inside.Add(Comments(h, null));
        }
        return Concat(T(node.Tokens[0]), Nest(profile.Number("indent"), Concat(inside)), Hardline(), TokenWith(close, g));
    }
    Document Body(SyntaxNode node) {
        Document separator = profile.Kr ? Text(" ") : Hardline();
        if (node.Kind == "block") return Concat(separator, Block(node));
        Document document = Statement(node);
        if (profile.Yes("add_braces")) return Concat(separator, Text("{"), Nest(profile.Number("indent"), Concat(Hardline(), document)), Hardline(), Text("}"));
        return Nest(profile.Number("indent"), Concat(Hardline(), document));
    }
    Document Simple(SyntaxNode node) => node.Kind == "assign" ? Concat(Expression(node.Children[0], 0), Space(), T(node.Tokens[0]), Space(), Expression(node.Children[1], 0)) : Expression(node.Children[0], 0);
    Document Clause(SyntaxNode node) {
        List<Document> parts = new() {
            T(node.Tokens[0])
        };
        int first = node.Kind == "case" ? 1 : 0;
        if (first == 1) parts.AddRange(new[] {
            Text(" "), Expression(node.Children[0], 0)
        });
        parts.Add(T(node.Tokens[1]));
        if (node.Children.Count > first) {
            List<Document> statements = new() {
                Hardline()
            };
            for (int i = first; i < node.Children.Count; i++) {
                SyntaxNode child = node.Children[i];
                if (i > first) statements.Add(Separator(Preblank(child.Start)));
                statements.Add(Statement(child));
            }
            parts.Add(Nest(profile.Number("indent"), Concat(statements)));
        }
        return Concat(parts);
    }
    Document Statement(SyntaxNode node) {
        switch (node.Kind) {
            case "block": return Block(node);
            case "decl": return Declaration(node);
            case "statement": return Concat(Simple(node.Children[0]), T(node.Tokens[0]));
            case "break": case "continue": return Concat(node.Tokens.Select(T));
            case "return": {
                List<Document> parts = new() {
                    T(node.Tokens[0])
                };
                if (node.Children.Count > 0) parts.AddRange(new[] {
                    Text(" "), Expression(node.Children[0], 0)
                });
                parts.Add(T(node.Tokens[1]));
                return Concat(parts);
            }
            case "while": case "if": {
                Document condition = Expression(node.Children[0], 0), body = Body(node.Children[1]);
                List<Document> parts = new() {
                    T(node.Tokens[0]), KeywordSpace(), T(node.Tokens[1]), condition, T(node.Tokens[2]), body
                };
                if (node.Kind == "if" && node.Children.Count == 3) {
                    parts.Add(profile.Kr && (node.Children[1].Kind == "block" || profile.Yes("add_braces")) ? Text(" ") : Hardline());
                    parts.Add(T(node.Tokens[3]));
                    if (node.Children[2].Kind == "if") parts.AddRange(new[] {
                        Text(" "), Statement(node.Children[2])
                    });
                    else parts.Add(Body(node.Children[2]));
                }
                return Concat(parts);
            }
            case "for": {
                List<Document> inner = new();
                SyntaxNode initial = node.Children[0];
                if (initial.Kind != "empty") inner.Add(initial.Kind == "decl" ? Declaration(initial) : Simple(initial));
                inner.Add(T(node.Tokens[2]));
                if (node.Children[1].Kind != "empty") inner.AddRange(new[] {
                    Line(), Expression(node.Children[1], 0)
                });
                inner.Add(T(node.Tokens[3]));
                if (node.Children[2].Kind != "empty") inner.AddRange(new[] {
                    Line(), Simple(node.Children[2])
                });
                Document group = Group(Align(Concat(inner))), body = Body(node.Children[3]);
                return Concat(T(node.Tokens[0]), KeywordSpace(), T(node.Tokens[1]), group, T(node.Tokens[4]), body);
            }
            case "switch": {
                int close = node.Tokens[4];
                var (h, g) = Closing(close);
                Document condition = Expression(node.Children[0], 0);
                List<Document> parts = new() {
                    T(node.Tokens[0]), KeywordSpace(), T(node.Tokens[1]), condition, T(node.Tokens[2]), profile.Kr ? Text(" ") : Hardline(), T(node.Tokens[3])
                };
                if (node.Children.Count > 1 || h.Count > 0) {
                    List<Document> inside = new() {
                        Hardline()
                    };
                    for (int i = 1; i < node.Children.Count; i++) {
                        SyntaxNode child = node.Children[i];
                        if (i > 1) inside.Add(Separator(Preblank(child.Start)));
                        inside.Add(Clause(child));
                    }
                    if (h.Count > 0) {
                        if (node.Children.Count > 1) inside.Add(Separator(h[0].Blank));
                        inside.Add(Comments(h, null));
                    }
                    parts.AddRange(new[] {
                        Nest(profile.Yes("indent_case_labels") ? profile.Number("indent") : 0, Concat(inside)), Hardline()
                    });
                }
                parts.Add(TokenWith(close, g));
                return Concat(parts);
            }
            default: throw new InvalidOperationException();
        }
    }
    public Document Function(SyntaxNode node) {
        Document parameters = List(node.Children[0]), block = Block(node.Children[1]);
        return Concat(T(node.Tokens[0]), Text(" "), T(node.Tokens[1]), parameters, Hardline(), block);
    }
    Document Postfix(SyntaxNode node) => node.Kind switch {
        "call" => List(node.Children[1]), "index" => Concat(T(node.Tokens[0]), Expression(node.Children[1], 0), T(node.Tokens[1])), "member" => Concat(T(node.Tokens[0]), T(node.Tokens[1])), _ => throw new InvalidOperationException()
    };
    Document Expression(SyntaxNode original, int required) {
        SyntaxNode node = Open(original, required);
        switch (node.Kind) {
            case "atom": return T(node.Tokens[0]);
            case "paren": return Concat(T(node.Tokens[0]), Expression(node.Children[0], 0), T(node.Tokens[1]));
            case "unary": return Concat(T(node.Tokens[0]), Expression(node.Children[0], 8));
            case "binary": {
                int p = Level(node);
                SyntaxNode current = node;
                List<(int Op, SyntaxNode Right)> entries = new();
                while (current.Kind == "binary" && Level(current) == p) {
                    entries.Add((current.Tokens[0], current.Children[1]));
                    current = Open(current.Children[0], p);
                }
                Document head = Expression(current, p);
                List<Document> rest = new();
                foreach (var (op, right) in entries.AsEnumerable().Reverse()) rest.AddRange(new[] {
                    OperatorLine(), T(op), Space(), Expression(right, p + 1)
                });
                return Group(Concat(head, Nest(profile.Number("indent"), Concat(rest))));
            }
            case "conditional": {
                Document head = Expression(node.Children[0], 1);
                SyntaxNode current = node;
                List<Document> rest = new();
                while (true) {
                    rest.AddRange(new[] {
                        OperatorLine(), T(current.Tokens[0]), Space(), Expression(current.Children[1], 0), OperatorLine(), T(current.Tokens[1]), Space()
                    });
                    SyntaxNode next = Open(current.Children[2], 0);
                    if (next.Kind == "conditional") {
                        rest.Add(Expression(next.Children[0], 1));
                        current = next;
                    } else {
                        rest.Add(Expression(next, 0));
                        break;
                    }
                }
                return Group(Concat(head, Nest(profile.Number("indent"), Concat(rest))));
            }
            case "call": case "index": case "member": {
                SyntaxNode current = node;
                List<SyntaxNode> operations = new();
                while (current.Kind is "call" or "index" or "member") {
                    operations.Add(current);
                    current = Open(current.Children[0], 8);
                }
                List<List<SyntaxNode>> segments = new() {
                    new()
                };
                foreach (SyntaxNode operation in operations.AsEnumerable().Reverse()) {
                    if (operation.Kind == "member") segments.Add(new());
                    segments[^1].Add(operation);
                }
                List<int> calls = Enumerable.Range(1, segments.Count - 1).Where(i => segments[i].Any(op => op.Kind == "call")).ToList();
                List<Document> parts = new() {
                    Expression(current, 8)
                };
                if (calls.Count < 2) {
                    foreach (SyntaxNode operation in segments.SelectMany(segment => segment)) parts.Add(Postfix(operation));
                    return Concat(parts);
                }
                int first = calls[0];
                foreach (SyntaxNode operation in segments.Take(first).SelectMany(segment => segment)) parts.Add(Postfix(operation));
                List<Document> rest = new();
                foreach (List<SyntaxNode> segment in segments.Skip(first)) {
                    rest.Add(Softline());
                    foreach (SyntaxNode operation in segment) rest.Add(Postfix(operation));
                }
                parts.Add(Nest(profile.Number("indent"), Concat(rest)));
                return Group(Concat(parts));
            }
            default: throw new InvalidOperationException();
        }
    }
}
sealed record Formatted(List<string> Lines, (string Name, Document Document)? FirstFunction, Dictionary<int, string> Modes, int Comments);
sealed record Source(string Header, string Name, string Profile) {
    public List<string> Lines {
        get;
    } = new();
}
static class Program {
    static (List<Token> Tokens, int Comments) Attach(Lexed lexed) {
        List<Token> tokens = lexed.Tokens;
        for (int k = 0; k < lexed.Order.Count; k++) {
            Occurrence entry = lexed.Order[k];
            if (entry.IsToken) continue;
            Comment comment = lexed.Comments[entry.Index];
            int? previous = lexed.Order.Take(k).Where(o => o.IsToken).Select(o => (int?)o.Index).LastOrDefault();
            int? next = lexed.Order.Skip(k + 1).Where(o => o.IsToken).Select(o => (int?)o.Index).FirstOrDefault();
            int? nextLine = null;
            if (k + 1 < lexed.Order.Count) {
                Occurrence following = lexed.Order[k + 1];
                nextLine = following.IsToken ? tokens[following.Index].Line : lexed.Comments[following.Index].Line;
            }
            comment.Own = comment.LineComment || !nextLine.HasValue || nextLine.Value > comment.Line;
            bool trailing = previous.HasValue && tokens[previous.Value].Line == comment.Line && (next == null || tokens[next.Value].Line > comment.Line);
            if (trailing) tokens[previous!.Value].Trailing.Add(comment);
            else tokens[next ?? tokens.Count - 1].Leading.Add(comment);
        }
        return (tokens, lexed.Comments.Count);
    }
    static void CheckComments(List<SyntaxNode> items, List<Token> tokens) {
        HashSet<int> allowed = new() {
            tokens.Count - 1
        }, tails = new();
        void Walk(SyntaxNode node) {
            switch (node.Kind) {
                case "block": allowed.Add(node.Tokens[1]);
                foreach (SyntaxNode child in node.Children) allowed.Add(child.Start);
                break;
                case "switch": allowed.Add(node.Tokens[4]);
                foreach (SyntaxNode clause in node.Children.Skip(1)) {
                    allowed.Add(clause.Tokens[0]);
                    foreach (SyntaxNode statement in clause.Children.Skip(clause.Kind == "case" ? 1 : 0)) allowed.Add(statement.Start);
                } break;
                case "if": if (node.Children[1].Kind != "block") allowed.Add(node.Children[1].Start);
                if (node.Children.Count == 3 && node.Children[2].Kind is not ("block" or "if")) allowed.Add(node.Children[2].Start);
                break;
                case "while": if (node.Children[1].Kind != "block") allowed.Add(node.Children[1].Start);
                break;
                case "for": if (node.Children[3].Kind != "block") allowed.Add(node.Children[3].Start);
                break;
                case "params": case "args": case "initlist": foreach (SyntaxNode child in node.Children) allowed.Add(child.Start);
                if (node.Trailing is int tail) tails.Add(tail);
                break;
            }
            foreach (SyntaxNode child in node.Children) Walk(child);
        }
        foreach (SyntaxNode item in items) {
            allowed.Add(item.Start);
            Walk(item);
        }
        for (int i = 0; i < tokens.Count; i++) foreach (Comment comment in tokens[i].Leading) if (comment.Own && !allowed.Contains(i) || tails.Contains(i)) throw new SourceError(comment.Line, comment.Column, "comment not allowed here");
    }
    static Formatted FormatSource(IReadOnlyList<string> lines, Profile profile) {
        var (tokens, commentCount) = Attach(Lexer.Lex(lines));
        List<SyntaxNode> items = Parser.Parse(tokens);
        CheckComments(items, tokens);
        bool empty = items.Count == 0 && tokens[^1].Leading.Count == 0;
        Construction builder = new(tokens, profile);
        List<Document> parts = new();
        (string Name, Document Document)? firstFunction = null;
        for (int i = 0; i < items.Count; i++) {
            SyntaxNode node = items[i];
            if (i > 0) parts.Add(builder.Separator(builder.Preblank(node.Start)));
            Document document = node.Kind == "function" ? builder.Function(node) : builder.Declaration(node);
            if (node.Kind == "function" && firstFunction == null) firstFunction = (builder.Tokens[node.Tokens[1]].Text, document);
            parts.Add(document);
        }
        List<Comment> closing = builder.Tokens[^1].Leading;
        if (closing.Count > 0) {
            if (items.Count > 0) parts.Add(builder.Separator(closing[0].Blank));
            parts.Add(builder.Comments(closing, null));
        }
        if (empty) return new(new(), firstFunction, new(), commentCount);
        Printed printed = Printer.Print(Concat(parts), profile.Number("width"), profile.Number("comment_column"));
        return new(printed.Lines, firstFunction, printed.Modes, commentCount);
    }
    static (Dictionary<string, Profile> Profiles, List<Source> Sources) Inputs() {
        Dictionary<string, Profile> profiles = new();
        string current = "";
        foreach (string line in File.ReadAllLines("input/style.txt")) {
            if (line.Length == 0) continue;
            if (line.StartsWith('[')) {
                current = line[1..^1];
                profiles[current] = new();
            } else {
                string[] pair = line.Split('=', 2);
                profiles[current].Values[pair[0]] = pair[1];
            }
        }
        List<Source> sources = new();
        foreach (string line in File.ReadAllLines("input/sources.txt")) {
            if (line.StartsWith("=== ", StringComparison.Ordinal)) {
                string[] parts = line.Split(' ');
                sources.Add(new(line, parts[1], parts[2]));
            } else sources[^1].Lines.Add(line);
        } return (profiles, sources);
    }
    static void Write(string name, List<string> lines) {
        Directory.CreateDirectory("output");
        File.WriteAllText("output/" + name, lines.Count == 0 ? "" : string.Join("\n", lines) + "\n");
    }
    static void Main() {
        CultureInfo.CurrentCulture = CultureInfo.InvariantCulture;
        CultureInfo.CurrentUICulture = CultureInfo.InvariantCulture;
        var (profiles, sources) = Inputs();
        List<string> formatted = new(), idempotency = new(), diagnostics = new(), docTree = new(), changes = new();
        foreach (Source source in sources) {
            Profile profile = profiles[source.Profile];
            List<string> original = source.Lines.Select(Lexer.Trim).ToList();
            formatted.Add(source.Header);
            docTree.Add("=== " + source.Name);
            changes.Add("=== " + source.Name);
            try {
                Formatted first = FormatSource(source.Lines, profile);
                formatted.AddRange(first.Lines);
                try {
                    Formatted second = FormatSource(first.Lines, profile);
                    if (first.Lines.SequenceEqual(second.Lines)) idempotency.Add(source.Name + ": stable");
                    else {
                        int index = 0;
                        while (index < Math.Min(first.Lines.Count, second.Lines.Count) && first.Lines[index] == second.Lines[index]) index++;
                        idempotency.Add($"{source.Name}: unstable at line {index + 1}");
                    }
                }
                catch (SourceError error) {
                    idempotency.Add($"{source.Name}: unstable (second pass: {error.Line}:{error.Column}: {error.Reason})");
                }
                int width = profile.Number("width");
                for (int i = 0; i < first.Lines.Count; i++) if (first.Lines[i].Length > width) diagnostics.Add($"{source.Name}:{i + 1}: warning: line too long ({first.Lines[i].Length} > {width})");
                int longest = first.Lines.Select(line => line.Length).DefaultIfEmpty(0).Max(), broken = first.Modes.Values.Count(mode => mode != "flat"), forced = first.Modes.Values.Count(mode => mode == "forced");
                docTree.Add($"metrics lines={first.Lines.Count} longest={longest} comments={first.Comments} groups={first.Modes.Count} broken={broken} forced={forced}");
                if (first.FirstFunction is {
                } function) {
                    docTree.Add("function " + function.Name);
                    Report.Tree(function.Document, 0, first.Modes, docTree);
                } else docTree.Add("no function");
                changes.AddRange(Report.Diff(original, first.Lines));
            } catch (SourceError error) {
                formatted.AddRange(original);
                idempotency.Add(source.Name + ": skipped (syntax error)");
                diagnostics.Add($"{source.Name}:{error.Line}:{error.Column}: error: {error.Reason}");
                docTree.Add("syntax error");
                changes.Add("skipped (syntax error)");
            }
        }
        if (diagnostics.Count == 0) diagnostics.Add("no diagnostics");
        Write("formatted.txt", formatted);
        Write("idempotency.txt", idempotency);
        Write("diagnostics.txt", diagnostics);
        Write("doc_tree.txt", docTree);
        Write("changes.txt", changes);
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
static class Report {
    public static void Tree(Document document, int depth, IReadOnlyDictionary<int, string> modes, List<string> output) {
        string prefix = new(' ', depth * 2);
        switch (document) {
            case Document.Concat c: foreach (Document part in c.Children) Tree(part, depth, modes, output);
            break;
            case Document.Text t: output.Add(prefix + $"text \"{t.Value}\"");
            break;
            case Document.Suffix s: output.Add(prefix + $"suffix \"{s.Value}\"");
            break;
            case Document.IfBreak b: output.Add(prefix + $"if_break \"{b.Broken}\" \"{b.Flat}\"");
            break;
            case Document.Group g: output.Add(prefix + $"group {modes[g.Id]}");
            Tree(g.Child, depth + 1, modes, output);
            break;
            case Document.Nest n: output.Add(prefix + $"nest {n.Amount}");
            Tree(n.Child, depth + 1, modes, output);
            break;
            case Document.Align a: output.Add(prefix + "align");
            Tree(a.Child, depth + 1, modes, output);
            break;
            case Document.Line: output.Add(prefix + "line");
            break;
            case Document.Softline: output.Add(prefix + "softline");
            break;
            case Document.Hardline: output.Add(prefix + "hardline");
            break;
            case Document.BreakParent: output.Add(prefix + "break_parent");
            break;
        }
    }
    public static List<string> Diff(IReadOnlyList<string> a, IReadOnlyList<string> b) {
        int n = a.Count, m = b.Count;
        int[,] lcs = new int[n + 1, m + 1];
        for (int x = n - 1; x >= 0; x--) for (int y = m - 1; y >= 0; y--) lcs[x, y] = a[x] == b[y] ? lcs[x + 1, y + 1] + 1 : Math.Max(lcs[x + 1, y], lcs[x, y + 1]);
        int i = 0, j = 0, deleted = 0, inserted = 0;
        List<List<string>> hunks = new();
        while (i < n || j < m) {
            if (i < n && j < m && a[i] == b[j]) {
                i++;
                j++;
                continue;
            }
            int i0 = i, j0 = j, d = 0, e = 0;
            List<string> lines = new();
            while (i < n || j < m) {
                if (i < n && j < m && a[i] == b[j]) break;
                if (j == m || i < n && lcs[i + 1, j] >= lcs[i, j + 1]) {
                    lines.Add("-" + a[i++]);
                    d++;
                } else {
                    lines.Add("+" + b[j++]);
                    e++;
                }
            }
            deleted += d;
            inserted += e;
            hunks.Add(new() {
                $"@@ -{(d > 0 ? i0 + 1 : i0)},{d} +{(e > 0 ? j0 + 1 : j0)},{e} @@"
            });
            hunks[^1].AddRange(lines);
        }
        List<string> result = new() {
            $"hunks={hunks.Count} deleted={deleted} inserted={inserted}"
        };
        result.AddRange(hunks.SelectMany(x => x));
        return result;
    }
}
